-- Rice: colours from the wallpaper (colors/rice.lua is generated by matugen via rice-wall),
-- a glass background, a small start screen and a text-only statusline to match the terminal.

local function palette()
  return vim.g.rice_palette or {}
end

-- Start screen header: greeting like the terminal's, then the date and palette dots
local function greeting()
  local h = tonumber(os.date("%H"))
  local hello = h < 5 and "good night" or h < 12 and "good morning" or h < 17 and "good afternoon" or "good evening"
  local dots = {}
  for _, g in ipairs({ "RiceRed", "RiceGreen", "RiceYellow", "RiceBlue", "RiceMagenta", "RiceCyan" }) do
    table.insert(dots, { "● ", hl = g })
  end
  return {
    { text = { { "󰣇  ", hl = "SnacksDashboardIcon" }, { hello .. ", ", hl = "SnacksDashboardDesc" }, { vim.env.USER, hl = "SnacksDashboardKey" } }, align = "center" },
    { text = { { os.date("%A, %d %B"), hl = "SnacksDashboardFooter" } }, align = "center", padding = 1 },
    { text = dots, align = "center", padding = 2 },
  }
end

-- Statusline theme: text only — every section on the glass, coloured text, no blocks
local function lualine_theme()
  local p = palette()
  local function mode(color)
    return {
      a = { fg = color, bg = "NONE", gui = "bold" },
      b = { fg = p.subtle, bg = "NONE" },
      c = { fg = p.subtle, bg = "NONE" },
    }
  end
  return {
    normal = mode(p.primary),
    insert = mode(p.green),
    visual = mode(p.tertiary),
    replace = mode(p.red),
    command = mode(p.yellow),
    terminal = mode(p.cyan),
    inactive = { a = { fg = p.outline, bg = "NONE" }, b = { fg = p.outline, bg = "NONE" }, c = { fg = p.outline, bg = "NONE" } },
  }
end

return {
  { "nvim-mini/mini.base16", lazy = false, priority = 1000 },
  { "LazyVim/LazyVim", opts = { colorscheme = "rice" } },

  -- Small start screen (replaces the big LAZYVIM logo)
  {
    "folke/snacks.nvim",
    opts = function(_, opts)
      opts.dashboard = opts.dashboard or {}
      opts.dashboard.sections = function()
        local sections = greeting()
        vim.list_extend(sections, {
          { section = "keys", gap = 1, padding = 2 },
          { icon = " ", title = "Recent files", section = "recent_files", indent = 2, padding = 2 },
          { section = "startup" },
        })
        return sections
      end
    end,
  },

  -- Text-only statusline in wallpaper colours
  {
    "nvim-lualine/lualine.nvim",
    opts = function(_, opts)
      opts.options = opts.options or {}
      opts.options.theme = lualine_theme()
      opts.options.section_separators = { left = "", right = "" }
      opts.options.component_separators = { left = "", right = "" }
    end,
  },

  -- Buffer tabs on the glass too (the current one stands out by colour, not a block)
  {
    "akinsho/bufferline.nvim",
    opts = function(_, opts)
      opts.highlights = function(config)
        local h = {}
        for name, _ in pairs(config.highlights) do
          h[name] = { bg = "NONE" }
        end
        return h
      end
    end,
  },
}
